local a={}local b={}aeslua=b;local c=require("utils.aeslua.ciphermode")local d=require("utils.aeslua.util")b.AES128=16;b.AES192=24;b.AES256=32;b.ECBMODE=1;b.CBCMODE=2;b.OFBMODE=3;b.CFBMODE=4;function a.pwToKey(e,f)local g=f;if(f==b.AES192)then g=32 end;if(g>#e)then local h=""for i=1,g-#e do h=h..string.char(0)end;e=e..h else e=string.sub(e,1,g)end;local j={string.byte(e,1,#e)}e=c.encryptString(j,e,c.encryptCBC)e=string.sub(e,1,f)return{string.byte(e,1,#e)}end;function b.encrypt(e,k,f,l)assert(e~=nil,"Empty password.")assert(e~=nil,"Empty data.")local l=l or b.CBCMODE;local f=f or b.AES128;local m=a.pwToKey(e,f)local n=d.padByteString(k)if(l==b.ECBMODE)then return c.encryptString(m,n,c.encryptECB)elseif(l==b.CBCMODE)then return c.encryptString(m,n,c.encryptCBC)elseif(l==b.OFBMODE)then return c.encryptString(m,n,c.encryptOFB)elseif(l==b.CFBMODE)then return c.encryptString(m,n,c.encryptCFB)else return nil end end;function b.decrypt(e,k,f,l)local l=l or b.CBCMODE;local f=f or b.AES128;local m=a.pwToKey(e,f)local o;if(l==b.ECBMODE)then o=c.decryptString(m,k,c.decryptECB)elseif(l==b.CBCMODE)then o=c.decryptString(m,k,c.decryptCBC)elseif(l==b.OFBMODE)then o=c.decryptString(m,k,c.decryptOFB)elseif(l==b.CFBMODE)then o=c.decryptString(m,k,c.decryptCFB)end;result=d.unpadByteString(o)if(result==nil)then return nil end;return result end